style.css:
@-moz-document url-prefix("http") {
::selection {
    background-color: rgba(255, 255, 255, 0.5); /* Fondo blanco semitransparente */
    color: black; /* Color del texto */
  }
  /* Para navegadores que usan ::-moz-selection */
  ::-moz-selection {
    background-color: rgba(255, 255, 255, 0.5);
    color: black;
  }
}
